begin;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$ begin if v is distinct from true then raise exception 'Failed: %',label; end if; end $$;
create function pg_temp.denied(q text) returns void language plpgsql as $$ begin begin execute q; exception when insufficient_privilege then return; end; raise exception 'Expected permission denial'; end $$;
insert into auth.users(id,email_confirmed_at) values('76000000-0000-4000-8000-000000000001',now()),('76000000-0000-4000-8000-000000000002',now()),('76000000-0000-4000-8000-000000000003',now());
insert into private.market_projects(id,buyer_id,status,brief,agreement) values('76000000-0000-4000-8000-000000000010','76000000-0000-4000-8000-000000000001','agreement','{"title":"Synthetic private brief"}','{"confidentiality":"Private agreement"}'),('76000000-0000-4000-8000-000000000011','76000000-0000-4000-8000-000000000001','open','{"title":"Synthetic open brief"}',null);
insert into private.market_conversations(id,kind,status,initiator_id,recipient_id) values('76000000-0000-4000-8000-000000000012','direct','active','76000000-0000-4000-8000-000000000001','76000000-0000-4000-8000-000000000002');
set local role anon;
select pg_temp.ok(public.market_project_detail('76000000-0000-4000-8000-000000000011')->'project'->'brief'->>'title'='Synthetic open brief','anonymous open discovery retained');
select pg_temp.denied($q$select public.market_project_detail('76000000-0000-4000-8000-000000000010')$q$);
select pg_temp.denied('select * from public.market_inbox_events');
reset role;
select pg_temp.ok(not has_table_privilege('anon','public.market_inbox_events','TRUNCATE'),'anonymous truncate revoked');
select pg_temp.ok(not has_table_privilege('authenticated','public.market_inbox_events','TRUNCATE'),'member truncate revoked');
select pg_temp.ok(not has_table_privilege('authenticated','public.market_inbox_events','INSERT,UPDATE,DELETE'),'member mutation grants revoked');
set local role authenticated;
select set_config('request.jwt.claim.sub','76000000-0000-4000-8000-000000000001',true);
select pg_temp.ok(public.market_project_detail('76000000-0000-4000-8000-000000000010')->'project'->'agreement'->>'confidentiality'='Private agreement','active participant private detail');
select pg_temp.ok((select count(*)=1 from public.market_inbox_events where conversation_id='76000000-0000-4000-8000-000000000012'),'active participant sees own event only');
select pg_temp.denied('select private.market_list_projects()');
select pg_temp.denied($q$select private.market_project_detail('76000000-0000-4000-8000-000000000010')$q$);
select set_config('request.jwt.claim.sub','76000000-0000-4000-8000-000000000003',true);
select pg_temp.ok((select count(*)=0 from public.market_inbox_events where conversation_id='76000000-0000-4000-8000-000000000012'),'unrelated JWT cannot see recipient events');
select pg_temp.denied($q$select public.market_project_detail('76000000-0000-4000-8000-000000000010')$q$);
reset role;
update auth.users set banned_until=now()+interval '1 day' where id='76000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','76000000-0000-4000-8000-000000000001',true);
select pg_temp.denied('select public.market_list_projects()');
select pg_temp.denied($q$select public.market_project_detail('76000000-0000-4000-8000-000000000010')$q$);
select pg_temp.ok((select count(*)=0 from public.market_inbox_events where conversation_id='76000000-0000-4000-8000-000000000012'),'banned account cannot read realtime events');
reset role;
update auth.users set banned_until=null,email_confirmed_at=null where id='76000000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.denied('select public.market_list_projects()');
select pg_temp.ok((select count(*)=0 from public.market_inbox_events where conversation_id='76000000-0000-4000-8000-000000000012'),'unconfirmed account cannot read events');
reset role;
update auth.users set email_confirmed_at=now(),deleted_at=now() where id='76000000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.denied('select public.market_list_projects()');
select pg_temp.ok((select count(*)=0 from public.market_inbox_events where conversation_id='76000000-0000-4000-8000-000000000012'),'deleted account cannot read events');
reset role;
update auth.users set deleted_at=null where id='76000000-0000-4000-8000-000000000001';
insert into public.basic_onboarding_applications(user_id,full_name,email,phone,linkedin_url,date_of_birth,status) values('76000000-0000-4000-8000-000000000001','Synthetic revoked account','synthetic@example.test','+919999999999','https://www.linkedin.com/in/synthetic-account','1990-01-01','revoked');
set local role authenticated;
select pg_temp.denied('select public.market_list_projects()');
select pg_temp.denied($q$select public.market_project_detail('76000000-0000-4000-8000-000000000010')$q$);
select pg_temp.ok((select count(*)=0 from public.market_inbox_events where conversation_id='76000000-0000-4000-8000-000000000012'),'revoked account cannot read events');
reset role;
-- A proposal does not permanently establish current provider eligibility.
insert into public.talent_profiles(id,data) values('selection-provider-test','{"name":"Synthetic provider","linkedinUrl":"https://www.linkedin.com/in/selection-provider-test"}');
insert into private.talent_owners(profile_id,user_id) values('selection-provider-test','76000000-0000-4000-8000-000000000002');
