set local role authenticated;
select set_config('request.jwt.claim.sub','76000000-0000-4000-8000-000000000002',true);
select public.market_project_action('76000000-0000-4000-8000-000000000020','propose','{"approach":"Test approach","schedule":"One week","ipTerms":"Source delivery","confidentiality":"Private","revisions":1,"milestones":[{"title":"Test board","deliverables":"Editable sources","acceptance":"DRC passes","serviceAmount":1000,"materialsAmount":0}]}')->'proposals'->0->>'id' as selection_proposal \gset
reset role;
update public.talent_profiles set published=false where id='selection-provider-test';
set local role authenticated;
select set_config('request.jwt.claim.sub','76000000-0000-4000-8000-000000000003',true);
select pg_temp.denied(format('select public.market_project_action(%L,''select_provider'',%L)','76000000-0000-4000-8000-000000000020',jsonb_build_object('proposalId',:'selection_proposal')::text));
reset role;
update public.talent_profiles set published=true where id='selection-provider-test';
insert into public.basic_onboarding_applications(user_id,full_name,email,phone,linkedin_url,date_of_birth,status) values('76000000-0000-4000-8000-000000000002','Synthetic provider','provider@example.test','+918888888888','https://www.linkedin.com/in/selection-provider-test','1990-01-01','revoked');
set local role authenticated;
select pg_temp.denied(format('select public.market_project_action(%L,''select_provider'',%L)','76000000-0000-4000-8000-000000000020',jsonb_build_object('proposalId',:'selection_proposal')::text));
reset role;
delete from public.basic_onboarding_applications where user_id='76000000-0000-4000-8000-000000000002';
set local role authenticated;
select pg_temp.ok(public.market_project_action('76000000-0000-4000-8000-000000000020','select_provider',jsonb_build_object('proposalId',:'selection_proposal'))->'project'->>'provider_id'='76000000-0000-4000-8000-000000000002','current eligible provider selected');
reset role;
rollback;
